/* Bounded local MP4 metadata reads; no upload or external decoder dependency. */
'use strict';
(function(root){
const number=(v,offset)=>v.getUint32(offset)*4294967296+v.getUint32(offset+4);
function boxes(bytes,start=0,end=bytes.length){const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),out=[];for(let p=start;p+8<=end;){let size=v.getUint32(p),head=8;const type=String.fromCharCode(...bytes.subarray(p+4,p+8));if(size===1){if(p+16>end)break;size=number(v,p+8);head=16;}else if(size===0)size=end-p;if(!Number.isSafeInteger(size)||size<head||p+size>end)break;out.push({type,start:p+head,end:p+size});p+=size;}return out;}
function parseMoov(bytes){const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),children=b=>boxes(bytes,b.start,b.end),top=boxes(bytes),moov=top.find(b=>b.type==='moov'),tracks=(moov?children(moov):top).filter(b=>b.type==='trak');for(const track of tracks){const mdia=children(track).find(b=>b.type==='mdia');if(!mdia)continue;const nodes=children(mdia),handler=nodes.find(b=>b.type==='hdlr'),header=nodes.find(b=>b.type==='mdhd'),minf=nodes.find(b=>b.type==='minf');if(!handler||!header||!minf||handler.start+12>handler.end)continue;if(String.fromCharCode(...bytes.subarray(handler.start+8,handler.start+12))!=='vide')continue;const off=header.start+(bytes[header.start]===1?20:12);if(off+4>header.end)continue;const scale=view.getUint32(off),stbl=children(minf).find(b=>b.type==='stbl'),stts=stbl&&children(stbl).find(b=>b.type==='stts');if(!stts||stts.start+8>stts.end||!scale)continue;const entries=view.getUint32(stts.start+4),deltas=[];let count=0,ticks=0;for(let i=0;i<entries&&stts.start+8+(i+1)*8<=stts.end;i++){const p=stts.start+8+i*8,n=view.getUint32(p),delta=view.getUint32(p+4);if(!delta||!n)continue;count+=n;ticks+=n*delta;deltas.push({count:n,seconds:delta/scale});}if(count<2||!ticks)continue;const average=count*scale/ticks,common=[15,23.976,24,25,29.97,30,50,59.94,60,100,119.88,120],fps=common.reduce((a,b)=>Math.abs(b-average)<Math.abs(a-average)?b:a,common[0]);return{fps:Math.abs(fps-average)/average<.003?fps:average,average,frames:count,duration:ticks/scale,variable:deltas.some(d=>d.count>count*.01&&Math.abs(d.seconds*average-1)>.12),method:'MP4 stts',deltas};}return null;}
async function read(file,signal){for(let p=0,seen=0;p+8<=file.size&&seen<10000;seen++){if(signal?.aborted)throw new DOMException('已取消','AbortError');const head=new Uint8Array(await file.slice(p,p+16).arrayBuffer()),v=new DataView(head.buffer);if(head.length<8)break;let size=v.getUint32(0);const type=String.fromCharCode(...head.subarray(4,8));if(size===1){if(head.length<16)break;size=number(v,8);}else if(size===0)size=file.size-p;if(!Number.isSafeInteger(size)||size<8||p+size>file.size)break;if(type==='moov'){if(size>32*1024*1024)throw Error('视频索引过大，请手动确认帧率');return parseMoov(new Uint8Array(await file.slice(p,p+size).arrayBuffer()));}p+=size;}return null;}
function fromPresentation(samples){const rows=samples.slice(1).map((p,i)=>({dt:p.time-samples[i].time,frames:p.frames-samples[i].frames})).filter(p=>p.dt>0&&p.frames>0);if(rows.length<4)return null;const estimates=rows.map(p=>p.frames/p.dt).sort((a,b)=>a-b),fps=estimates[Math.floor(estimates.length/2)];return fps>=10&&fps<=240?{fps,average:fps,method:'浏览器呈现时间估计',variable:estimates.some(v=>Math.abs(v/fps-1)>.18)}:null;}
root.DCRecVideoMeta={boxes,parseMoov,read,fromPresentation};
})(typeof window==='undefined'?globalThis:window);
